  if(Math.abs(x-8)<(depth<160?16:11)&&depth<340)return;
  if(depth<75){const clusters=[[84,-79],[-42,-93],[43,-116],[122,-106],[165,-112]];if(!clusters.some(([cx,cz])=>Math.hypot(x-cx,z-cz)<13))return;}
