 const density=(x,z)=>{let n=0;const bx=Math.floor(x/20),bz=Math.floor(z/20);for(let dx=-1;dx<=1;dx++)for(let dz=-1;dz<=1;dz++)for(const r of forestBins.get((bx+dx)+','+(bz+dz))||[])n+=Math.max(0,1-Math.hypot(x-r.x,z-r.z)/19);return Math.max(0,Math.min(.96,(n-1.0)*.72));};
 const floor=new geometryBuilder(),points=[],colors=[],uv=[],indices=[],cells=new Set();for(const r of records)if(r.zone==='Mischwald'||r.zone==='Höhere Hänge'||/Waldzone|Bergwald/.test(r.zone))for(let dx=-2;dx<=2;dx++)for(let dz=-2;dz<=2;dz++)cells.add((Math.floor(r.x/8)+dx)+','+(Math.floor(r.z/8)+dz));let floorCells=0;const under=new Kit(group),fg=geometryBuilder();for(let arm=0;arm<8;arm++){const a=arm*2.4,start=new T.Vector3(0,0,0),tip=new T.Vector3(Math.cos(a)*.8,.6+arm%3*.1,Math.sin(a)*.8);fg.tube(start,tip,.014,.004,[.1,.24,.06],4);for(let j=1;j<9;j++)for(const sign of [-1,1]){const p=start.clone().lerp(tip,j/9),length=.26*(1-j/11);fg.leaf(p,length,.045,a+sign*1.15,-.9,[.08,.30,.055]);}}const fern=fg.finish(),floorMaskCells=new Set();
 for(const key of cells){const [ix,iz]=key.split(',').map(Number),x=ix*8,z=iz*8;if(density(x+4,z+4)<.18||blocked(x+4,z+4,6))continue;const vs=[[x,z],[x+8,z],[x+8,z+8],[x,z+8]],ys=vs.map(p=>surface(...p));if(ys.some(y=>y===null))continue;const base=points.length/3;vs.forEach(([px,pz],i)=>{const a=density(px,pz);points.push(px,ys[i]+.008,pz);colors.push(.14,.18+.055*Math.sin(px*.34),.07,a);uv.push(px/2,pz/2);});indices.push(base,base+1,base+2,base,base+2,base+3);floorCells++;floorMaskCells.add(key);
 if(random()<.35){const cx=x+4,cz=z+4,cy=surface(cx,cz);under.put(fern,foliage,cx,cy,cz,1,1,1,0,random()*6.28,0);under.line(bark,[cx-1,cy+.08,cz],[cx+1.6,cy+.1,cz+.5],.065);}}
 if(points.length){const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(points,3));g.setAttribute('color',new T.Float32BufferAttribute(colors,4));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(indices);g.computeVertexNormals();const mat=new T.MeshStandardMaterial({name:'Alpiner Waldboden – Moos und Laubstreu',color:'#ffffff',vertexColors:true,roughness:1,transparent:true,depthWrite:false,side:T.DoubleSide});const mesh=new T.Mesh(g,mat);mesh.name='Nahtloser Waldboden nur unter dichtem Mischwald';mesh.userData={newForestFloor:true,terrainPreserved:true};mesh.receiveShadow=true;group.add(mesh);}
 under.finish();scene.forestFloorMask=(x,z)=>floorMaskCells.has(Math.floor(x/8)+','+Math.floor(z/8))?density(x,z):0;let removedFlowers=0;meadowController.records.forEach(rows=>{for(let i=rows.length-1;i>=0;i--)if(scene.forestFloorMask(rows[i].x,rows[i].z)>.66){rows.splice(i,1);removedFlowers++;}});if(!mobile)meadowController.prepareExport();
